{
  "name": "DG645数字延迟发生器",
  "name_en": "DG645 Digital Delay Generator",
  "manufacturer": "Stanford Research Systems",
  "description": "这是一台数字延迟发生器，用于在触发事件后输出具有可编程时间延迟的定时脉冲。该设备可配置延迟通道、触发源与触发速率、触发保持时间、突发模式，以及输出极性、幅度和偏置，常用于激光同步、时序分配和通用实验触发控制。",
  "description_en": "This is a digital delay generator used to produce precisely timed pulses with programmable delays relative to a trigger event. It supports configuration of delay channels, trigger source and rate, trigger holdoff, burst mode, and output polarity, amplitude, and offset, making it useful for laser synchronization, timing distribution, and general experimental trigger control.",
  "tag_hints": [
    "digital delay generator",
    "pulse timing",
    "trigger control",
    "burst mode",
    "laser synchronization",
    "SCPI instrument",
    "programmable delay"
  ],
  "actions": [
    {
      "action_name": "auto-burst_count",
      "description": "获取/设置突发计数",
      "description_en": "get/set burst count"
    },
    {
      "action_name": "auto-burst_delay",
      "description": "获取/设置突发延迟",
      "description_en": "get/set burst delay"
    },
    {
      "action_name": "auto-burst_period",
      "description": "获取/设置突发周期",
      "description_en": "get/set burst period"
    },
    {
      "action_name": "auto-display",
      "description": "获取/设置前面板显示模式",
      "description_en": "get/set front-panel display mode"
    },
    {
      "action_name": "auto-enable_adv_triggering",
      "description": "获取/设置高级触发启用状态",
      "description_en": "get/set advanced triggering enable state"
    },
    {
      "action_name": "auto-enable_burst_mode",
      "description": "获取/设置突发模式启用状态",
      "description_en": "get/set burst mode enable state"
    },
    {
      "action_name": "auto-enable_burst_t0_first",
      "description": "获取/设置突发模式下T0仅首个周期输出状态",
      "description_en": "get/set T0-first behavior in burst mode"
    },
    {
      "action_name": "auto-holdoff",
      "description": "获取/设置触发保持时间",
      "description_en": "get/set trigger holdoff time"
    },
    {
      "action_name": "auto-trigger_rate",
      "description": "获取/设置内部触发速率",
      "description_en": "get/set internal trigger rate"
    },
    {
      "action_name": "auto-trigger_source",
      "description": "获取/设置触发源",
      "description_en": "get/set trigger source"
    },
    {
      "action_name": "auto-channel",
      "description": "获取指定通道",
      "description_en": "get specified channel"
    },
    {
      "action_name": "auto-output",
      "description": "获取指定输出端口",
      "description_en": "get specified output port"
    },
    {
      "action_name": "auto-idx",
      "description": "获取通道或输出编号",
      "description_en": "get channel or output index"
    },
    {
      "action_name": "auto-delay",
      "description": "获取/设置通道延迟",
      "description_en": "get/set channel delay"
    },
    {
      "action_name": "auto-polarity",
      "description": "获取/设置输出极性",
      "description_en": "get/set output polarity"
    },
    {
      "action_name": "auto-level_amplitude",
      "description": "获取/设置输出幅度",
      "description_en": "get/set output amplitude"
    },
    {
      "action_name": "auto-level_offset",
      "description": "获取/设置输出偏置",
      "description_en": "get/set output offset"
    }
  ]
}

